  enum class state_word_e : std::size_t {
    center = 0u,
    inverse_scale = 1u,
    convergence_curve = 2u,
    container_scale = 3u,
    calibration_revision = 4u,
    frame_valid = 5u,
    confirmed_cut_count = 6u,
    contract_tag_bits = 7u,
    camera_center_integrity_bits = 8u,
    renderer_authorization_bits = 9u,
    mapping_state_reserved_1 = 10u,
    mapping_state_reserved_2 = 11u,
    count = 12u,
  };

  constexpr std::size_t state_index(const state_word_e word) {
    return static_cast<std::size_t>(word);
  }

  inline constexpr std::size_t center = state_index(state_word_e::center);
  inline constexpr std::size_t inverse_scale = state_index(state_word_e::inverse_scale);
  inline constexpr std::size_t convergence_curve = state_index(state_word_e::convergence_curve);
  inline constexpr std::size_t container_scale = state_index(state_word_e::container_scale);
  inline constexpr std::size_t calibration_revision = state_index(state_word_e::calibration_revision);
  inline constexpr std::size_t frame_valid = state_index(state_word_e::frame_valid);
  inline constexpr std::size_t confirmed_cut_count = state_index(state_word_e::confirmed_cut_count);
  inline constexpr std::size_t contract_tag_bits = state_index(state_word_e::contract_tag_bits);
  inline constexpr std::size_t camera_center_integrity_bits = state_index(state_word_e::camera_center_integrity_bits);
  inline constexpr std::size_t renderer_authorization_bits = state_index(state_word_e::renderer_authorization_bits);
  inline constexpr std::size_t mapping_state_reserved_1 = state_index(state_word_e::mapping_state_reserved_1);
  inline constexpr std::size_t mapping_state_reserved_2 = state_index(state_word_e::mapping_state_reserved_2);

  inline constexpr std::size_t state_float_count =
    state_index(state_word_e::count);
  inline constexpr std::size_t state_vector_width = 4u;
  inline constexpr std::size_t state_vector_count =
    state_float_count / state_vector_width;
  using state_words_t = std::array<std::uint32_t, state_float_count>;

  struct state_field_descriptor_t {
    state_word_e word;
    std::string_view name;
    std::string_view json_type;
    state_gpu_encoding_e gpu_encoding;
    std::uint32_t initial_word;
  };

  inline constexpr std::array<state_field_descriptor_t, 12> state_fields {{
    {state_word_e::center, "center", "float32", state_gpu_encoding_e::float_value, std::bit_cast<std::uint32_t>(0.0f)},
    {state_word_e::inverse_scale, "inverse_scale", "float32", state_gpu_encoding_e::float_value, std::bit_cast<std::uint32_t>(0.0f)},
    {state_word_e::convergence_curve, "convergence_curve", "float32", state_gpu_encoding_e::float_value, std::bit_cast<std::uint32_t>(0.0f)},
    {state_word_e::container_scale, "container_scale", "float32", state_gpu_encoding_e::float_value, std::bit_cast<std::uint32_t>(1.0f)},
    {state_word_e::calibration_revision, "calibration_revision", "uint32", state_gpu_encoding_e::uint_bits, 0u},
    {state_word_e::frame_valid, "frame_valid", "float32", state_gpu_encoding_e::float_value, std::bit_cast<std::uint32_t>(0.0f)},
    {state_word_e::confirmed_cut_count, "confirmed_cut_count", "uint32", state_gpu_encoding_e::uint_bits, 0u},
    {state_word_e::contract_tag_bits, "contract_tag_bits", "uint32", state_gpu_encoding_e::uint_bits, contract_tag},
    {state_word_e::camera_center_integrity_bits, "camera_center_integrity_bits", "uint32", state_gpu_encoding_e::uint_bits, 0u},
    {state_word_e::renderer_authorization_bits, "renderer_authorization_bits", "uint32", state_gpu_encoding_e::uint_bits, 0u},
    {state_word_e::mapping_state_reserved_1, "mapping_state_reserved_1", "uint32", state_gpu_encoding_e::uint_bits, 0u},
    {state_word_e::mapping_state_reserved_2, "mapping_state_reserved_2", "uint32", state_gpu_encoding_e::uint_bits, 0u},
  }};

  inline constexpr std::array<const char *, state_float_count> state_field_names {{
    "center",
    "inverse_scale",
    "convergence_curve",
    "container_scale",
    "calibration_revision",
    "frame_valid",
    "confirmed_cut_count",
    "contract_tag_bits",
    "camera_center_integrity_bits",
    "renderer_authorization_bits",
    "mapping_state_reserved_1",
    "mapping_state_reserved_2",
  }};

  inline constexpr state_words_t state_initial_words {{
    std::bit_cast<std::uint32_t>(0.0f),
    std::bit_cast<std::uint32_t>(0.0f),
    std::bit_cast<std::uint32_t>(0.0f),
    std::bit_cast<std::uint32_t>(1.0f),
    0u,
    std::bit_cast<std::uint32_t>(0.0f),
    0u,
    contract_tag,
    0u,
    0u,
    0u,
    0u,
  }};

  constexpr bool state_field_layout_matches_indices() {
    for (std::size_t position = 0; position < state_fields.size(); ++position) {
      if (state_index(state_fields[position].word) != position) {
        return false;
      }
    }
    return true;
  }

  constexpr bool state_word_is_uint_bits(const state_word_e word) {
    return state_fields[state_index(word)].gpu_encoding ==
      state_gpu_encoding_e::uint_bits;
  }

  constexpr bool contract_tag_is_finite_normal(const std::uint32_t value) {
    const auto exponent = (value >> 23u) & 0xffu;
    return exponent > 0u && exponent < 0xffu;
  }

  static_assert(frame_stats_float_count % 4u == 0u);
  static_assert(state_float_count % state_vector_width == 0u);
  static_assert(state_field_layout_matches_indices());
  static_assert(contract_tag != 0u);
  static_assert(contract_tag_is_finite_normal(contract_tag));
  static_assert(state_initial_words[state_index(state_word_e::contract_tag_bits)] ==
                contract_tag);
